"""One remaining roster master only. Process ends/relinquishes source memory before next identity."""
from PIL import Image
import pathlib,json,hashlib,sys,datetime,gc
base=pathlib.Path(__file__).resolve().parent;root=base.parents[2]
id=sys.argv[1];roi=list(map(int,sys.argv[2:6]));assert len(roi)==4
roster=json.loads((root/'assets/characters/motion-generated/roster-skin-mapping-20261028.json').read_text(encoding='utf-8'))
slot=next(s for s in roster['slots']if s['appearance']['identityId']==id);assert slot['sourceRoleId']not in[11,13,14,15,16]
master=root.joinpath(*pathlib.PurePosixPath(slot['appearance']['master']).parts);source_record_rel=slot['appearance']['sourceRecord'];source_record_path=root.joinpath(*pathlib.PurePosixPath(source_record_rel).parts);source_record=json.loads(source_record_path.read_text(encoding='utf-8'))
raw=master.read_bytes();sha=hashlib.sha256(raw).hexdigest()
expected=slot['appearance'].get('recordedSourceSha256')or source_record.get('sha256')
if expected and sha!=expected:raise ValueError('Master no longer matches exact roster/source record: '+id)
im=Image.open(master).convert('RGBA');source_size=list(im.size);l,t,r,b=roi;assert 0<=l<r<=im.width and 0<=t<b<=im.height
crop=im.crop(tuple(roi));w,h=crop.size;s=228/max(w,h);rw=round(w*s);rh=round(h*s);assert abs(rw/w-rh/h)<1e-12,'Choose integer ROI preserving exact uniform rasterized x/y scale'
piece=crop.convert('RGBa').resize((rw,rh),Image.Resampling.LANCZOS).convert('RGBA');xy=[(256-rw)//2,(256-rh)//2];portrait=Image.new('RGBA',(256,256),(0,0,0,0));portrait.paste(piece,tuple(xy))
dest=base/(id+'-256.png');portrait.save(dest);a=portrait.getchannel('A');bb=a.point(lambda v:255 if v>=8 else 0).getbbox();assert bb
edge={'left':sum(a.getpixel((0,y))>=8 for y in range(256)),'right':sum(a.getpixel((255,y))>=8 for y in range(256)),'top':sum(a.getpixel((x,0))>=8 for x in range(256)),'bottom':sum(a.getpixel((x,255))>=8 for x in range(256))};assert not any(edge.values())
generation=source_record.get('generation',{})
rec={'schemaVersion':1,'file':'assets/characters/portraits-candidates/'+dest.name,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceRoleId':slot['sourceRoleId'],'identityId':id,'name':slot['appearance']['displayName'],'type':'derived_ui_portrait_candidate_existing_character_not_new_generation','mappingRecord':'assets/characters/motion-generated/roster-skin-mapping-20261028.json','source':{'file':slot['appearance']['master'],'sha256':sha,'sourceCanvasSize':source_size,'sourceProvenanceRecord':source_record_rel,'sourceGenerationRecord':source_record_rel,'sourceGenerationRecordType':'historical source/provenance including generation evidence if present, not a new model receipt','nativeGenerationSize':None,'nativeGenerationSizeEvidence':'Historical compatibility/export PNG dimensions only; native model generation dimensions unverified. Do not call4096 canvas native4K.','actualModel':generation.get('actualModel',source_record.get('actualModel')),'actualQuality':generation.get('actualQuality',source_record.get('actualQuality')),'provenanceSnapshot':source_record},'operation':{'kind':'one manually selected complete head/hair/headwear/face and upper collar ROI; whole ROI uniform premultiplied-alpha LANCZOS downscale and centered transparent256 canvas','sourceCropLTRB':roi,'sourceCropSize':[w,h],'uniformScale':s,'resampledCropSize':[rw,rh],'placementXY':xy,'outputCanvas':[256,256],'requestedTransparentInset':14,'sourceMasterAndRecordActuallyViewed':True,'noComponentMovement':True,'noFaceSeparateScale':True,'noMirroring':True,'newImageGeneration':False},'output':{'alphaExtrema':a.getextrema(),'alpha8BBoxLTRB':bb,'alpha8MarginsLTRB':[bb[0],bb[1],256-bb[2],256-bb[3]],'alpha8OuterEdges':edge,'preview':'assets/characters/portraits-candidates/qa/'+id+'-256-ivory.png','actual256Viewed':False},'runtimeAdopted':False,'clientApproved':False,'status':'portrait_candidate_pending_actual256_visual_review'}
dest.with_suffix('.png.source.json').write_text(json.dumps(rec,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
qa=base/'qa';qa.mkdir(exist_ok=True);preview=qa/(id+'-256-ivory.png');ivory=Image.new('RGBA',(256,256),(246,240,222,255));ivory.alpha_composite(portrait);ivory.convert('RGB').save(preview)
preview.with_suffix('.png.source.json').write_text(json.dumps({'derivedFrom':{'file':rec['file'],'sha256':rec['sha256'],'sourceRecord':rec['file']+'.source.json'},'operation':'One actual256px ivory preview only; no source rescan/new generation.'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'sourceRoleId':rec['sourceRoleId'],'identity':id,'sourceCanvasSize':source_size,'nativeGenerationSize':None,'sourceROI':roi,'scale':s,'outputSize':[256,256],'visibleMargins':rec['output']['alpha8MarginsLTRB'],'runtimeAdopted':False},ensure_ascii=False))
del raw,im,crop,piece,portrait,ivory,a;gc.collect()
